      document.body.append(dialog);
      function validate(){const current=model.evaluateBunchNoteRowAndIssues(p.row,state.bunchContext,{...state.draft.choices,note:state.draft.note});const errors=current.blockers.map(b=>'Rule '+b[0]+': '+b[1]).concat(current.bunchNoteIssues.map(i=>'Rule '+i.rule+': '+i.reason));if(!state.draft.note.trim())errors.push('Enter a Bunch Note.');if(state.loading||!cache.loaded||options.inventoryReady?.()===false)errors.push('Review remains open while the complete inventory and reference snapshot loads.');dialog.querySelector('[data-bunch-blockers]').textContent=errors.join(' ');dialog.querySelector('[data-bunch-approve]').disabled=errors.length>0||state.pending.has('ph_dylan_decisions_store:'+p.plan_id);return current;}
      dialog.addEventListener('input',event=>{if(event.target.matches('[data-bunch-note]')){state.draft.note=event.target.value;state.draft.dirty=true;validate();}});
