    function cardDraft(p){if(!state.cardDrafts.has(p.uid))state.cardDrafts.set(p.uid,ownedCache.failedDrafts.get(p.uid)||{uid:p.uid,choices:{...p.choices},note:p.saved?.notes||p.autoSuggestedBunchNote});return state.cardDrafts.get(p.uid);}
    function locationCards(){return state.currentIssues.filter(p=>p.location===state.location).sort((a,b)=>a.location.localeCompare(b.location,undefined,{numeric:true})||a.itemcode.localeCompare(b.itemcode,undefined,{numeric:true})||String(readRow(a.row,'lotcode')).localeCompare(String(readRow(b.row,'lotcode'))));}
